async function scanBundle(input, deliver) {
  let delivered = 0;
  let lineNumber = 1;
  let pending = "";

  try {
    const decoder = new TextDecoder("utf-8");

    const consumeLine = async (line, lineNumber) => {
      if (/^[ \t\r]*$/.test(line)) return true;

      let value;
      try {
        value = JSON.parse(line);
      } catch {
        const error = new Error(`Invalid JSON on line ${lineNumber}`);
        error.code = "BAD_LINE";
        error.line = lineNumber;
        throw error;
      }

      delivered++;
      return (await deliver(value, lineNumber)) !== false;
    };

    const consumeText = async (text) => {
      let start = 0;

      while (true) {
        const end = text.indexOf("\n", start);
        if (end === -1) {
          pending += text.slice(start);
          return true;
        }

        pending += text.slice(start, end);

        if (!(await consumeLine(pending.endsWith("\r") ? pending.slice(0, -1) : pending, lineNumber))) {
          return false;
        }

        pending = "";
        lineNumber++;
        start = end + 1;
      }
    };

    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        if (!(await consumeText(decoder.decode()))) return delivered;

        if (pending.length > 0) {
          await consumeLine(
            pending.endsWith("\r") ? pending.slice(0, -1) : pending,
            lineNumber
          );
        }

        return delivered;
      }

      if (!(await consumeText(decoder.decode(chunk, { stream: true })))) {
        return delivered;
      }
    }
  } finally {
    await input.close();
  }
}
